def normalize(S):
 mnr=min(r for r,c in S); mnc=min(c for r,c in S)
 return frozenset((r-mnr,c-mnc) for r,c in S)
def trans_shapes(S):
 out=[]
 for refl in (False,True):
  for k in range(4):
   T={(r,-c if refl else c) for r,c in S}
   for _ in range(k): T={(c,-r) for r,c in T}
   T=normalize(T)
   if T not in out:out.append(T)
 return out
def matches(grid,S):
 h,w=len(grid),len(grid[0]); H=max(r for r,c in S)+1; W=max(c for r,c in S)+1
 return [(r,c) for r in range(h-H+1) for c in range(w-W+1) if all(grid[r+dr][c+dc]==0 for dr,dc in S)]
